    # 判断是否为偶数
    if num % 2 == 0:
        has_even = True
    else:
        cnt_odd += 1  # 奇数计数加一

# 如果没有偶数，则输出-1
if not has_even:
    print(-1)
else:
    # 否则输出奇数的个数
    print(cnt_odd)
