## Java 

```java
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        // 读取数组长度n
        int n = sc.nextInt();
        int cntOdd = 0; // 奇数计数
        boolean hasEven = false; // 是否存在偶数

        // 遍历数组中的每个元素
        for (int i = 0; i < n; i++) {
            int a = sc.nextInt();
            // 判断a是否为偶数
            if (a % 2 == 0) {
                hasEven = true;
            } else {
                cntOdd++; // 奇数计数加一
            }
        }
        // 如果数组中没有偶数，则输出-1
        if (!hasEven) {
            System.out.println(-1);
        } else {
            // 否则输出奇数的个数
            System.out.println(cntOdd);
        }
        sc.close();
    }
}
